INSERT INTO projects (code, name_ar, name_en, description_ar, description_en, status, start_date, planned_end_date, budget_sar, sponsoring_department_ar, sponsoring_department_en) VALUES
('PRJ-01', 'منصة التحول الرقمي للخدمات المالية', 'Financial Services Digital Transformation Platform', 'مبادرة لتحويل الخدمات المالية الداخلية إلى منصة رقمية موحدة تشمل طلبات الصرف والاعتمادات والمطالبات. تهدف المنصة إلى إلغاء الدورة الورقية بالكامل وربطها بنظام الموارد المؤسسية. تشمل المرحلة الحالية إطلاق ثلاث خدمات تجريبية لعدد من الجهات المشاركة.', 'An initiative to migrate internal financial services onto a single digital platform covering disbursement requests, approvals, and claims. The platform aims to eliminate the paper-based cycle entirely and integrate with the enterprise resource system. The current phase covers the pilot launch of three services across selected participating entities.', 'on-track', '2025-03-01', '2026-12-31', 42500000, 'الإدارة العامة لتقنية المعلومات', 'General Directorate of Information Technology'),
('PRJ-02', 'بوابة الخدمات الحكومية الموحدة "خدماتي"', 'Unified Citizen Services Portal ("Khadamati")', 'بوابة موحدة تتيح للمستفيدين الوصول إلى الخدمات الحكومية من نقطة دخول واحدة عبر النفاذ الوطني الموحد. يشمل النطاق تصميم رحلة المستفيد وإعادة هندسة ثمانٍ من الخدمات الأكثر استخداماً. يواجه المشروع تأخراً في تكامل بعض الجهات المشاركة.', 'A unified portal giving beneficiaries single-entry access to government services via national single sign-on. Scope includes beneficiary journey design and the re-engineering of eight of the most frequently used services. The project is facing delays in integration with several participating entities.', 'at-risk', '2025-06-15', '2026-11-30', 28750000, 'إدارة تجربة المستفيد', 'Beneficiary Experience Department'),
('PRJ-03', 'منصة البيانات الوطنية للحوكمة', 'National Governance Data Platform', 'بناء منصة بيانات مركزية لتجميع ومعالجة مؤشرات الحوكمة من الجهات الحكومية المشمولة. تشمل المنصة طبقة استيعاب البيانات ومستودعاً تحليلياً ولوحات مؤشرات تنفيذية. تأخر المشروع بسبب اكتمال جاهزية مصادر البيانات لدى الجهات وتغيّر متطلبات تصنيف البيانات.', 'Construction of a central data platform to consolidate and process governance indicators from in-scope government entities. The platform comprises an ingestion layer, an analytical warehouse, and executive indicator dashboards. The project has slipped due to source-system readiness at participating entities and changes to data classification requirements.', 'delayed', '2024-09-01', '2026-06-30', 61000000, 'إدارة حوكمة البيانات', 'Data Governance Department'),
('PRJ-04', 'تحديث البنية التحتية للشبكة الحكومية الآمنة', 'Secure Government Network Infrastructure Upgrade', 'تحديث شامل للبنية التحتية للشبكة في المقر الرئيسي وأربعة فروع، شمل استبدال أجهزة التوجيه والتبديل وتطبيق تجزئة الشبكة. نُفّذ المشروع على ثلاث مراحل دون انقطاع في الخدمات التشغيلية. اكتمل التسليم النهائي ونُقلت العمليات إلى فريق التشغيل.', 'A full refresh of network infrastructure across headquarters and four branch sites, including replacement of routing and switching equipment and implementation of network segmentation. Delivered in three phases with no interruption to operational services. Final handover is complete and operations have transferred to the run team.', 'completed', '2024-02-01', '2025-10-31', 37200000, 'الإدارة العامة للبنية التحتية والاتصالات', 'General Directorate of Infrastructure and Communications'),
('PRJ-05', 'نظام إدارة الأداء المؤسسي', 'Institutional Performance Management System', 'نظام لربط الخطة الاستراتيجية بالمبادرات والمؤشرات التشغيلية ومتابعة الأداء ربع السنوي. يشمل النطاق نمذجة المؤشرات وآلية اعتماد القياسات وتقارير الأداء للقيادة. المشروع في مرحلة التصميم التفصيلي ويسير وفق الخطة.', 'A system linking the strategic plan to initiatives and operational indicators with quarterly performance tracking. Scope includes indicator modelling, a measurement approval workflow, and leadership performance reporting. The project is in detailed design and is progressing according to plan.', 'on-track', '2025-09-01', '2027-03-31', 15400000, 'الإدارة العامة للتخطيط الاستراتيجي', 'General Directorate of Strategic Planning'),
('PRJ-06', 'أتمتة دورة إعداد الميزانية والاعتماد المالي', 'Budget Preparation and Financial Approval Automation', 'أتمتة دورة إعداد الميزانية السنوية بدءاً من تقديم تقديرات الجهات وحتى اعتماد المخصصات النهائية. يشمل النطاق نماذج التقديم الإلكترونية ومسارات الاعتماد متعددة المستويات ولوحة متابعة الانحرافات. يواجه المشروع مخاطر في الالتزام بالنافذة الزمنية لدورة الميزانية القادمة.', 'Automation of the annual budget preparation cycle from entity estimate submission through final appropriation approval. Scope covers electronic submission forms, multi-level approval routing, and a variance monitoring dashboard. The project carries risk against meeting the timing window of the upcoming budget cycle.', 'at-risk', '2025-01-15', '2026-09-30', 22900000, 'وكالة الميزانية العامة', 'General Budget Agency'),
('PRJ-07', 'منصة التكامل الحكومي وواجهات الربط', 'Government Integration and API Gateway Platform', 'منصة وسيطة لتوحيد الربط التقني بين الأنظمة الداخلية والجهات الحكومية الخارجية عبر بوابة واجهات مُدارة. يشمل النطاق كتالوج الواجهات وإدارة الهوية بين الأنظمة ومراقبة مستوى الخدمة. تأخر المشروع نتيجة إعادة تصميم طبقة الأمن بعد مراجعة الجهة التنظيمية.', 'A middleware platform standardising technical connectivity between internal systems and external government entities through a managed API gateway. Scope includes an API catalogue, system-to-system identity management, and service-level monitoring. The project was delayed by a redesign of the security layer following a regulatory review.', 'delayed', '2024-11-01', '2026-10-31', 33600000, 'مركز التكامل الرقمي', 'Digital Integration Center'),
('PRJ-08', 'مركز الاتصال الموحد لخدمة المستفيدين', 'Unified Beneficiary Contact Center', 'توحيد قنوات التواصل مع المستفيدين في مركز اتصال واحد يشمل الهاتف والمحادثة النصية والبريد الإلكتروني. شمل المشروع توريد نظام إدارة التذاكر وتأهيل الكوادر وبناء قاعدة معرفة موحدة للردود. اكتمل التشغيل الفعلي وتم إغلاق المشروع رسمياً.', 'Consolidation of beneficiary communication channels into a single contact center covering telephony, chat, and email. The project included procurement of a ticket management system, staff enablement, and construction of a unified response knowledge base. Live operation is complete and the project has been formally closed.', 'completed', '2024-05-01', '2025-12-15', 18300000, 'إدارة خدمات المستفيدين', 'Beneficiary Services Department'),
('TEST-PROJECT', 'مشروع تجريبي - عينات مستندات حقيقية', 'Test Project - Real Document Samples', 'مجموعة مستندات مشاريع حقيقية من مصادر متعددة، تُستخدم لاختبار خط أنابيب الاستيعاب والفهرسة بمحتوى واقعي متنوع البنية واللغة.', 'A collection of real project documents from multiple sources, used to test the ingestion pipeline against realistic, structurally and linguistically varied content rather than only the purpose-built fictional set.', 'testing', NULL, NULL, NULL, NULL, 'Data & AI')
